"""Freeze accepted, baseline, diagnostic and independent word-layout evidence."""
from datetime import datetime, timezone
from pathlib import Path
import hashlib, json, re, shutil

ROOT = Path(__file__).resolve().parents[2]
runtime = ROOT / 'product/.runtime'
out = ROOT / 'docs/validation/evidence'
def load(p): return json.loads(p.read_text(encoding='utf-8-sig'))
def sha(p): return 'sha256:' + hashlib.sha256(p.read_bytes()).hexdigest()
full, target, before = [load(runtime / f'word-layout-accepted-{mode}-20261016.json') for mode in ('full', 'targeted', 'before')]
public_path = ROOT / 'docs/assets/word-layout-20261016/evidence.json'
public = load(public_path)
independent = load(runtime / 'word-layout-independent-delivery-20261016.json')
policy = load(runtime / 'word-layout-policy-20261016.json')
assert full['status'] == 'passed' and full['test_count'] == 491
assert target['status'] == 'passed' and target['test_count'] == 21
assert before['test_count'] == 21 and before['exit_code'] == 1 and before['failure_records'] == 21
assert before['baseline_ref'] == public['baseline_ref'] == '7beb9ce0f2715f1c83067cc98f58e0a40c36d64b'
assert len(full['frozen_before']) == 95
for run in (full, target, before):
    assert run['frozen_before'] == run['frozen_after'] == public['frozen_before'] == public['frozen_after'] == full['frozen_before']
for p, digest in full['frozen_after'].items(): assert sha(ROOT / p) == digest, p
assert independent['public_evidence_sha256'] == sha(public_path)
assert independent['new_main_frames'] == independent['new_reference_frames'] == 632
assert len(public['calls']) == 90 and all(c['exit_code'] == 0 for c in public['calls'])
assert policy['count'] == policy['additional_cli_calls'] == 9 and all(c['exit_code'] == 0 for c in policy['calls'])
methods = set(re.findall(r'^    def (test_\w+)\(', (ROOT / 'product/tests/test_word_highlight.py').read_text(encoding='utf-8-sig'), re.M))
failed = set(re.findall(r'^(?:FAIL|ERROR): (test_\w+)', (runtime / 'word-layout-accepted-before-20261016.log').read_text(encoding='utf-8-sig'), re.M))
assert len(methods) == 21 and failed == methods
for name, results in independent['results'].items():
    after = results['after']
    assert after['max_rg_error'] <= 3 and after['bad_word_regions'] == after['max_source_frame_error'] == after['audio_mismatches'] == 0, name

logpaths = {f'word-layout-{mode}-20261016.log': runtime / f'word-layout-accepted-{mode}-20261016.log' for mode in ('full', 'targeted', 'before')}
for pattern in ('glyph-dev-*.log', 'word-layout-*-20261016.log', 'word-policy-*-20261016.log'):
    for p in sorted(runtime.glob(pattern)):
        if p.name.startswith('word-layout-accepted-'): continue
        logpaths[p.name] = p
logs = {}
for name, p in logpaths.items():
    dest = out / name
    if dest.exists(): assert dest.read_bytes() == p.read_bytes(), name
    else: shutil.copyfile(p, dest)
    logs[name] = {'sha256': sha(dest), 'bytes': dest.stat().st_size, 'is_accepted_full_regression': name == 'word-layout-full-20261016.log'}
for mode, record in [('full', full), ('targeted', target), ('before', before)]:
    assert record['log_sha256'] == logs[f'word-layout-{mode}-20261016.log']['sha256']
development = {}
for pattern in ('word-layout-final-*-20261016.json', 'word-layout-delivery-*-20261016.json'):
    for p in sorted(runtime.glob(pattern)):
        development[p.name] = {'accepted_current_source': False, 'record': load(p)}
for name in ('word-layout-delivery-full-20261016.json', 'word-layout-delivery-before-20261016.json'):
    assert development[name]['record']['test_count'] is None

helpers = ['verify_word_layout_20261016.py', 'audit_word_layout_20261016.py', 'audit_word_policy_20261016.py', 'publish_word_failures_20261016.py', 'audit_word_skills_20261016.py', 'audit_word_docs_20261016.py', 'update_word_docs_20261016.py', 'collect_word_evidence_20261016.py']
helper_files = {f'product/.runtime/{name}': {'sha256': sha(runtime / name), 'source': (runtime / name).read_text(encoding='utf-8-sig')} for name in helpers}
manual = [
    ('docs/assets/word-layout-20261016/contact-sheet.png', [0, 36, 71]),
    ('docs/assets/word-layout-20261016/selected-multiline.png', [40]),
    ('docs/assets/word-layout-20261016/selected-cjk.png', [40]),
    ('docs/assets/word-layout-failures-20261016/failed-vs-current.png', [4]),
]
public_hashes = {}
for folder in ('word-layout-20261016', 'word-layout-failures-20261016'):
    for p in sorted((ROOT / 'docs/assets' / folder).iterdir()):
        if p.is_file(): public_hashes[p.relative_to(ROOT).as_posix()] = {'sha256': sha(p), 'bytes': p.stat().st_size}
result = {
    'checked_at_utc': datetime.now(timezone.utc).isoformat(),
    'scope': '491-method full product regression; 21-method subset and the same methods on immutable old source; 90 public CLI calls plus 9 separate policy audits; independently decoded 27 variant videos. Diagnostic and failed development runs are separate.',
    'verification': {'full': full, 'targeted': target, 'before': before, 'baseline_failed_methods': sorted(failed)},
    'public_evidence_sha256': sha(public_path),
    'failure_evidence_sha256': sha(ROOT / 'docs/assets/word-layout-failures-20261016/failure-evidence.json'),
    'public_generator_sha256': sha(ROOT / 'scripts/smoke_word_layout.py'),
    'clock_oracle_sha256': sha(ROOT / 'scripts/smoke_speed_easing.py'),
    'public_files': public_hashes,
    'independent_delivery': independent,
    'local_policy': policy,
    'development_records': development,
    'failed_smoke_source_freeze': 'The two retained failed smokes did not independently freeze the then-current full source; they are failure artifacts, not accepted frozen-source proofs.',
    'manual_static_inspection': [{'path': p, 'source_frames': frames, 'sha256': sha(ROOT / p)} for p, frames in manual],
    'continuous_playback_reviewed': False, 'audio_listened': False,
    'skills_audit_sha256': sha(out / 'skills-audit-word-layout-20261016.json'),
    'helper_files': helper_files, 'logs': logs,
    'new_model_inference': 0,
    'remaining_limits': public['limits'] + ['arbitrary fontcolor opacity/color correctness', 'group spaces and buses', 'natural model quality', 'full Jianying equivalence'],
}
(out / 'word-layout-20261016.json').write_text(json.dumps(result, ensure_ascii=False, indent=2, allow_nan=False) + '\n', encoding='utf-8', newline='\n')
print(json.dumps({'full': full['test_count'], 'targeted_subset': target['test_count'], 'baseline_failed_methods': len(failed), 'source_and_schema_files': len(full['frozen_after']), 'raw_logs': len(logs), 'public_files': len(public_hashes), 'independent_main_frames': 632, 'independent_reference_frames': 632}))
